// ============================================================
// Voorraad Watch - vooruitkijkende seizoensberekening
// Kernvraag per maat: haal ik het einde van dit seizoen met wat er ligt?
// ============================================================
const cfgRows   = $('Merk-config').all().map(i => i.json);
const prodPages = $('CE: producten (alle maten)').all().map(i => i.json);
const ordPages  = $('CE: orders 53 weken').all().map(i => i.json);
const retPages  = $('CE: retouren 53 weken').all().map(i => i.json);
const stkPages  = $('CE: voorraadmutaties').all().map(i => i.json);
const shopOrd   = $('Shopify: orders').all().map(i => i.json);
const shopProd  = $('Shopify: producten').all().map(i => i.json);

const flat = (pages, k = 'Content') => pages.flatMap(p => p[k] || []);
const today = new Date();
const isoWeek = (d) => { const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  t.setUTCDate(t.getUTCDate() + 4 - (t.getUTCDay() || 7));
  const y = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
  return Math.ceil(((t - y) / 86400000 + 1) / 7); };
const NU = isoWeek(today);
const HORIZON_NOOS = 26;          // doorlopende artikelen: geen seizoenseinde

// ---- merk-config ----
const cfg = {};
for (const r of cfgRows) if (r.merk) cfg[String(r.merk).trim().toLowerCase()] = r;
const DEFAULT = { levertijd_dagen: 30, veiligheidsvoorraad_weken: 2, nabestellen_mogelijk: 'ja' };
const cfgFor = (m) => ({ ...DEFAULT, ...(cfg[String(m || '').trim().toLowerCase()] || {}) });

// ---- artikelstam uit ChannelEngine (alleen maatvarianten) ----
const ex = (p, k) => (p.ExtraData || []).find(e => e.Key === k)?.Value ?? null;
const seizoenVan = (s) => { s = (s || '').toLowerCase();
  if (/herfst|winter|autumn/.test(s)) return 'FW';
  if (/lente|zomer|spring|summer/.test(s)) return 'SS';
  return 'ONBEKEND'; };
const art = {}, eanNaar = {};
for (const p of flat(prodPages)) {
  if (!p.ParentMerchantProductNo) continue;
  const jaar = String(ex(p, 'Seizoensjaar') || '').toUpperCase();
  const a = { mpn: p.MerchantProductNo, merk: p.Brand, maat: p.Size, naam: p.Name,
    parent: p.ParentMerchantProductNo, voorraad: p.Stock || 0, prijs: p.Price || 0,
    inkoop: p.PurchasePrice || (p.Price || 0) * 0.45,
    type: jaar === 'NOOS' ? 'NOOS' : seizoenVan(ex(p, 'seizoen_NL') || ex(p, 'seizoen_EN')) };
  art[a.mpn] = a;
  if (p.Ean) eanNaar[p.Ean] = a.mpn;
}
const naarMpn = (sku) => (art[sku] ? sku : eanNaar[sku]);

// ---- vraag: webshop + marktplaats, per artikel per week ----
const vraag = {}, curve = {}, prijsMax = {}, betaald = [];
const tel = (mpn, w, q) => { (vraag[mpn] = vraag[mpn] || {})[w] = (vraag[mpn][w] || 0) + q; };
const telCurve = (sleutel, w, q) => { (curve[sleutel] = curve[sleutel] || {})[w] = (curve[sleutel][w] || 0) + q; };

for (const o of shopOrd) {
  if (o.cancelled_at) continue;
  const d = new Date(o.created_at); const w = isoWeek(d);
  const oud = (today - d) / 86400000;
  for (const li of o.line_items || []) {
    const mpn = naarMpn(li.sku); const q = li.quantity || 0;
    if (!mpn || q <= 0) continue;
    const a = art[mpn];
    const stuk = Number(li.price) || 0;
    prijsMax[mpn] = Math.max(prijsMax[mpn] || 0, stuk);
    betaald.push({ mpn, merk: a.merk, w, q, netto: stuk - (Number(li.total_discount) || 0) / q });
    telCurve(`${a.merk}|${a.type}`, w, q);
    if (oud <= 182) tel(mpn, w, q);
  }
}
for (const o of flat(ordPages)) {
  const d = new Date(o.OrderDate); const w = isoWeek(d);
  const oud = (today - d) / 86400000;
  for (const l of o.Lines || []) {
    if (l.Status === 'CANCELED') continue;
    const mpn = l.MerchantProductNo, q = l.Quantity || 0;
    if (!art[mpn] || q <= 0) continue;
    telCurve(`${art[mpn].merk}|${art[mpn].type}`, w, q);
    if (oud <= 182) tel(mpn, w, q);
  }
}

// ---- seizoensindex + seizoensdal per merk x type ----
const idx = {}, dal = {};
for (const [sleutel, c] of Object.entries(curve)) {
  const tot = Object.values(c).reduce((a, b) => a + b, 0);
  if (tot < 150) continue;
  const glad = {}, i = {};
  for (let w = 1; w <= 53; w++) {
    glad[w] = [-1, 0, 1].reduce((s, d) => s + (c[((w - 1 + d + 53) % 53) + 1] || 0), 0) / 3;
    i[w] = (c[w] || 0) / tot;
  }
  idx[sleutel] = i;
  dal[sleutel] = Object.keys(glad).reduce((a, b) => glad[a] <= glad[b] ? a : b);
}
// aandeel van de jaarvraag dat nog tussen nu en het seizoensdal valt
const restAandeel = (sleutel) => {
  if (!idx[sleutel]) return null;
  const d = Number(dal[sleutel]); let s = 0, w = NU, n = 0;
  while (w !== d && n < 53) { s += idx[sleutel][w]; w = (w % 53) + 1; n++; }
  return { aandeel: s, weken: n };
};
// aandeel van de jaarvraag in de afgelopen 26 weken (om de run-rate te schalen)
const verstreken = (sleutel) => {
  if (!idx[sleutel]) return null;
  let s = 0, w = NU;
  for (let k = 0; k < 26; k++) { w = ((w - 2 + 53) % 53) + 1; s += idx[sleutel][w]; }
  return s;
};

// ---- prijsregime per merk ----
// Een afprijzing in Shopify is meestal een lagere prijs, geen kortingscode.
// Daarom: aandeel stuks dat onder 92% van de eigen hoogste prijs wegging.
const perWeek = {};
for (const b of betaald) {
  const ref = prijsMax[b.mpn] || 0; if (ref <= 0) continue;
  const k = `${b.merk}|${b.w}`;
  const a = perWeek[k] = perWeek[k] || [0, 0];
  a[1] += b.q; if (b.netto < ref * 0.92) a[0] += b.q;
}
const liveSale = {};
for (const v of shopProd) {
  for (const va of v.variants || [v]) {
    const mpn = naarMpn(va.sku); if (!mpn) continue;
    const m = art[mpn].merk;
    const a = liveSale[m] = liveSale[m] || [0, 0];
    a[1]++;
    if (va.compare_at_price && Number(va.compare_at_price) > Number(va.price) * 1.02) a[0]++;
  }
}
const regime = {};
for (const m of new Set(Object.values(art).map(a => a.merk))) {
  const ws = [];
  for (let w = 1; w <= 53; w++) { const a = perWeek[`${m}|${w}`]; if (a && a[1] >= 20) ws.push([w, a[0] / a[1]]); }
  if (ws.length < 25) { regime[m] = { inSale: false, onbekend: true }; continue; }
  const gesorteerd = ws.map(x => x[1]).sort((a, b) => a - b);
  const basis = gesorteerd[Math.floor(gesorteerd.length / 2)];
  const nu = (ws.find(x => x[0] === NU) || [, null])[1];
  const lv = liveSale[m];
  const livePct = lv && lv[1] ? lv[0] / lv[1] : null;
  regime[m] = {
    basis: Math.round(100 * basis),
    nu: nu == null ? null : Math.round(100 * nu),
    live: livePct == null ? null : Math.round(100 * livePct),
    inSale: (nu != null && nu >= Math.max(0.30, basis + 0.20)) || (livePct != null && livePct >= 0.45),
  };
}

// ---- laatste voorraadmutatie (vangt ook verkoop die nergens als order landt) ----
const muteerde = {};
for (const s of flat(stkPages)) { const d = new Date(s.UpdatedAt); if (!isNaN(d)) muteerde[s.MerchantProductNo] = d; }
const stilDagen = (mpn) => muteerde[mpn] ? Math.round((today - muteerde[mpn]) / 86400000) : null;

const retour = {};
for (const r of flat(retPages)) for (const l of r.Lines || []) {
  if (l.MerchantProductNo) retour[l.MerchantProductNo] = (retour[l.MerchantProductNo] || 0) + (l.Quantity || 1);
}

// ---- besluit per maat ----
const out = [];
for (const a of Object.values(art)) {
  if (a.voorraad <= 0) continue;
  const c = cfgFor(a.merk), sleutel = `${a.merk}|${a.type}`;
  const v = vraag[a.mpn] || {};
  const recent = Object.values(v).reduce((x, y) => x + y, 0);   // 26 weken, alle kanalen
  const deel = verstreken(sleutel);
  if (!deel) continue;
  const jaarvraag = recent / deel;

  let rest, weken;
  if (a.type === 'NOOS') { weken = HORIZON_NOOS; rest = HORIZON_NOOS / 52; }
  else { const r = restAandeel(sleutel); if (!r) continue; rest = r.aandeel; weken = r.weken; }
  const restvraag = jaarvraag * rest;
  const projectie = a.voorraad - restvraag;

  const rg = regime[a.merk] || {};
  const horizon = Number(c.signaal_horizon_weken ||
    (Number(c.levertijd_dagen) / 7 + Number(c.veiligheidsvoorraad_weken)));
  const cutoff = c[a.type === 'FW' ? 'order_cutoff_fw' : 'order_cutoff_ss'];
  const nogTeBestellen = !cutoff || new Date(cutoff) > today;
  const stil = stilDagen(a.mpn);

  let signaal = 'OK', actie = '', prioriteit = 0;
  if (projectie < -0.5 && rg.inSale) {
    signaal = 'NIET-BIJBESTELLEN'; prioriteit = -projectie * a.prijs * 0.3;
    actie = 'Tekort, maar het merk zit al in de sale - vraag naar een lopend model sturen';
  } else if (projectie < -0.5 && c.nabestellen_mogelijk === 'nee') {
    signaal = 'TEKORT-NIET-LEVERBAAR'; prioriteit = -projectie * a.prijs * 0.5;
    actie = `Tekort van ${Math.ceil(-projectie)} st, maar dit merk levert niet na`;
  } else if (projectie < -0.5 && !nogTeBestellen) {
    signaal = 'TEKORT-NA-CUTOFF'; prioriteit = -projectie * a.prijs * 0.5;
    actie = `Tekort van ${Math.ceil(-projectie)} st, maar de order-cutoff (${cutoff}) is voorbij`;
  } else if (projectie < -0.5) {
    signaal = 'BIJBESTELLEN'; prioriteit = -projectie * a.prijs;
    actie = `Bestellen ~${Math.ceil(-projectie)} st - restvraag ${restvraag.toFixed(0)} st in ${weken} wk, `
          + `voorraad ${a.voorraad} st. Levertijd ${c.levertijd_dagen} dgn (horizon ${horizon.toFixed(1)} wk)`;
  } else if (a.type !== 'NOOS' && projectie > 0.5 && restvraag > 0.2 && !rg.inSale) {
    signaal = 'NU-AFPRIJZEN'; prioriteit = projectie * a.inkoop;
    actie = `Blijft ~${Math.round(projectie)} st over bij seizoenseinde (over ${weken} wk), nu nog volle prijs`;
  } else if (a.type !== 'NOOS' && projectie > 0.5 && rg.inSale) {
    signaal = 'KORTING-VERDIEPEN'; prioriteit = projectie * a.inkoop * 0.7;
    actie = `Blijft ~${Math.round(projectie)} st over en de sale loopt al - korting verdiepen of spreiden`;
  } else if (a.type === 'NOOS' && projectie > 0.5) {
    signaal = 'NOOS-TE-RUIM'; prioriteit = projectie * a.inkoop;
    const jaren = jaarvraag > 0 ? a.voorraad / jaarvraag : 99;
    actie = `${jaren > 99 ? '>99' : jaren.toFixed(1)} jaar voorraad tegen de huidige snelheid - inkoop stoppen`;
  } else if (recent === 0 && stil !== null && stil > 90) {
    signaal = 'STIL'; prioriteit = a.voorraad * a.inkoop;
    actie = `Geen verkoop en ${stil} dagen geen voorraadmutatie - uitfaseren`;
  }

  out.push({ json: {
    peildatum: today.toISOString().slice(0, 10), week: NU,
    merk: a.merk, artikel: a.naam, parent: a.parent, ean: a.mpn, maat: a.maat, type: a.type,
    voorraad: a.voorraad, verkocht_26w: recent,
    jaarvraag: Number(jaarvraag.toFixed(1)),
    restvraag: Number(restvraag.toFixed(1)), weken_tot_seizoenseinde: weken,
    projectie: Number(projectie.toFixed(1)),
    prijsregime: rg.inSale ? 'sale' : 'volle prijs',
    sale_nu_pct: rg.nu ?? null, sale_live_pct: rg.live ?? null,
    dagen_sinds_mutatie: stil,
    retour_52w: retour[a.mpn] || 0,
    verkoopprijs: a.prijs, inkoopprijs: Number(a.inkoop.toFixed(2)),
    voorraadwaarde: Number((a.voorraad * a.inkoop).toFixed(2)),
    signaal, actie, prioriteit_eur: Math.round(prioriteit),
  } });
}
out.sort((x, y) => y.json.prioriteit_eur - x.json.prioriteit_eur);
return out;

// Bouwt het weekrapport per merk
const rows = $input.all().map(i => i.json);
const perMerk = {};
for (const r of rows) {
  const m = perMerk[r.merk] = perMerk[r.merk] || { merk: r.merk, waarde: 0, teweinig: 0, teveel: 0, dead: 0, nee_verkoop: 0, top: [] };
  m.waarde += r.voorraadwaarde;
  if (r.signaal === 'TE-WEINIG') m.teweinig++;
  if (r.signaal === 'TE-VEEL' || r.signaal === 'TE-VEEL-SEIZOEN') m.teveel += r.prioriteit_eur;
  if (r.signaal === 'DEAD') m.dead += r.prioriteit_eur;
  if (r.signaal === 'NEE-VERKOOP') m.nee_verkoop++;
  if (r.signaal !== 'OK' && m.top.length < 10) m.top.push(r);
}
const merken = Object.values(perMerk).sort((a, b) => b.waarde - a.waarde);
const eur = n => '\u20ac ' + Math.round(n).toLocaleString('nl-NL');
let html = `<h2>Voorraad Watch \u2013 week ${rows[0]?.week}</h2>`;
html += '<table border=1 cellpadding=6 style="border-collapse:collapse"><tr><th>Merk</th><th>Voorraadwaarde</th><th>Maten te weinig</th><th>Nul-voorraad met vraag</th><th>Overstock \u20ac</th><th>Dead \u20ac</th></tr>';
for (const m of merken) html += `<tr><td>${m.merk}</td><td>${eur(m.waarde)}</td><td>${m.teweinig}</td><td>${m.nee_verkoop}</td><td>${eur(m.teveel)}</td><td>${eur(m.dead)}</td></tr>`;
html += '</table><h3>Top acties deze week</h3><ol>';
for (const r of rows.filter(r => r.signaal !== 'OK').slice(0, 25)) html += `<li><b>${r.merk}</b> \u2013 ${r.artikel} maat ${r.maat}: <b>${r.signaal}</b> \u2013 ${r.actie} <i>(${eur(r.prioriteit_eur)})</i></li>`;
html += '</ol>';
return [{ json: { html, week: rows[0]?.week } }];
